#!/usr/bin/env python3
# Generated by Claude Fable 5 (Anthropic)
"""Overhead ∝ event-rate regression (inventory item 1).

Per Isaac benchmark: x = LTTng event rate (events/s, from the traced runs'
'[FISH] LTTng events: N' lines ÷ run duration), y = throughput drop
(base fps − mode fps)/base fps [%], one series per mode (lttng, nsys).
Outputs scatter+fit figure (png/pdf) + a LaTeX data table.
"""
import glob
import os
import re
import csv
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

ROOT = os.path.expanduser('~/fish_traces/overhead_isaac')
BENCHES = ['apriltag', 'bi3d', 'bi3d_freespace', 'dnn_image_encoder', 'dope',
           'ess', 'image_proc', 'nvblox', 'segformer', 'stereo_image_proc',
           'tensor_rt', 'unet', 'visual_slam']


def event_rate(bench, mode):
    rates = []
    for d in glob.glob(f'{ROOT}/{bench}/{mode}_*'):
        lg = os.path.join(d, 'launch.log')
        try:
            txt = open(lg, errors='replace').read()
            m = re.search(r'LTTng events: ([\d,]+)', txt)
            t0 = float(open(os.path.join(d, 't_start.txt')).read())
            t1 = float(open(os.path.join(d, 't_end.txt')).read())
            if m and t1 > t0:
                rates.append(int(m.group(1).replace(',', '')) / (t1 - t0))
        except Exception:
            continue
    return sum(rates) / len(rates) if rates else None


def fps_table():
    out = {}
    with open(f'{ROOT}/summary.csv') as f:
        for r in csv.DictReader(f):
            try:
                out[(r['bench'], r['mode'])] = float(r['fps_mean'])
            except (ValueError, KeyError):
                pass
    return out


def main():
    fps = fps_table()
    rows = []
    for b in BENCHES:
        base = fps.get((b, 'base'))
        if not base:
            continue
        for mode in ('lttng', 'nsys'):
            fm = fps.get((b, mode))
            er = event_rate(b, mode)
            if fm and er:
                rows.append((b, mode, er, (base - fm) / base * 100))
    os.makedirs('paper/figures', exist_ok=True)
    os.makedirs('paper/tables', exist_ok=True)

    fig, ax = plt.subplots(figsize=(7.5, 5))
    COL = {'lttng': '#2c7fb8', 'nsys': '#d95f0e'}
    for mode in ('lttng', 'nsys'):
        pts = [(er, dr, b) for b, m, er, dr in rows if m == mode]
        if not pts:
            continue
        xs = [p[0] / 1e3 for p in pts]
        ys = [p[1] for p in pts]
        ax.scatter(xs, ys, color=COL[mode], s=28,
                   label=f'{mode} ({len(pts)} benchmarks)')
        n = len(xs)
        if n > 2:
            mx, my = sum(xs) / n, sum(ys) / n
            sxx = sum((x - mx) ** 2 for x in xs)
            sxy = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
            if sxx:
                b1 = sxy / sxx
                b0 = my - b1 * mx
                xr = [min(xs), max(xs)]
                ax.plot(xr, [b0 + b1 * x for x in xr], color=COL[mode],
                        ls='--', lw=1,
                        label=f'  fit: {b1:.3f} %/(k events/s)')
        for x, y, b in zip(xs, ys, [p[2] for p in pts]):
            ax.annotate(b, (x, y), fontsize=6, xytext=(3, 3),
                        textcoords='offset points', color='#555')
    ax.set_xlabel('LTTng event rate [k events/s]')
    ax.set_ylabel('throughput drop vs baseline [%]')
    ax.set_title('Tracing overhead scales with event volume (Isaac ROS, 13 benchmarks)')
    ax.grid(alpha=0.3)
    ax.axhline(0, color='#000', lw=0.6)
    ax.legend(fontsize=8)
    fig.tight_layout()
    for ext in ('png', 'pdf'):
        fig.savefig(f'paper/figures/overhead_vs_eventrate.{ext}', dpi=160)
    print('→ paper/figures/overhead_vs_eventrate.png/.pdf')

    L = ['% Generated by Claude Fable 5 (Anthropic)',
         r'\begin{table}[t]\centering\small',
         r'\caption{Event rate vs.\ throughput drop per benchmark.}'
         r'\label{tab:eventrate}',
         r'\begin{tabular}{lrrrr}', r'\toprule',
         r'benchmark & \multicolumn{2}{c}{LTTng-only} & '
         r'\multicolumn{2}{c}{LTTng+nsys} \\',
         r' & [kev/s] & drop [\%] & [kev/s] & drop [\%] \\', r'\midrule']
    per_bench = {}
    for b, m, er, dr in rows:
        per_bench.setdefault(b, {})[m] = (er, dr)
    for b in BENCHES:
        d = per_bench.get(b)
        if not d:
            continue
        el, dl = d.get('lttng', (None, None))
        en, dn = d.get('nsys', (None, None))
        fmt = lambda v, p=1: (f'{v:.{p}f}' if v is not None else '--')
        bn = b.replace('_', r'\_')
        L.append(f"{bn} & {fmt((el or 0)/1e3)} & {fmt(dl)} & "
                 f"{fmt((en or 0)/1e3)} & {fmt(dn)}" + r' \\')
    L += [r'\bottomrule', r'\end{tabular}', r'\end{table}']
    open('paper/tables/overhead_vs_eventrate.tex', 'w').write('\n'.join(L) + '\n')
    print('→ paper/tables/overhead_vs_eventrate.tex')


if __name__ == '__main__':
    main()
